   660  static void
   661  parse_accept_encoding(struct lwan_request *request)
   662  {
   663      struct lwan_request_parser_helper *helper = request->helper;
   664
   665      if (!helper->accept_encoding.len)
   666          return;
   667
   668      for (const char *p = helper->accept_encoding.value; *p; p++) {
   669          STRING_SWITCH(p) {
   670          case MULTICHAR_CONSTANT('d','e','f','l'):
   671          case MULTICHAR_CONSTANT(' ','d','e','f'):
   672              request->flags |= REQUEST_ACCEPT_DEFLATE;
   673              break;
   674          case MULTICHAR_CONSTANT('g','z','i','p'):
   675          case MULTICHAR_CONSTANT(' ','g','z','i'):
   676              request->flags |= REQUEST_ACCEPT_GZIP;
   677              break;
   678          }
   679
   680          if (!(p = strchr(p, ',')))
   681              break;
   682      }
   683  }
