   771  static enum lwan_http_status
   772  read_from_request_socket(struct lwan_request *request,
   773                           struct lwan_value *buffer,
   774                           const size_t buffer_size,
   775                           enum lwan_read_finalizer (*finalizer)(
   776                               size_t total_read,
   777                               size_t buffer_size,
   778                               struct lwan_request_parser_helper *helper,
   779                               int n_packets))
   780  {
   781      struct lwan_request_parser_helper *helper = request->helper;
   782      ssize_t n;
   783      size_t total_read = 0;
   784      int n_packets = 0;
   785
   786      if (helper->next_request) {
   787          buffer->len -= (size_t)(helper->next_request - buffer->value);
   788          /* FIXME: This memmove() could be eventually removed if a better
   789           * stucture were used for the request buffer. */
   790          memmove(buffer->value, helper->next_request, buffer->len);
   791          total_read = buffer->len;
   792          goto try_to_finalize;
   793      }
   794
   795      for (;; n_packets++) {
   796          n = read(request->fd, buffer->value + total_read,
   797                   (size_t)(buffer_size - total_read));
   798          /* Client has shutdown orderly, nothing else to do; kill coro */
   799          if (UNLIKELY(n == 0)) {
   800              coro_yield(request->conn->coro, CONN_CORO_ABORT);
   801              __builtin_unreachable();
   802          }
   803
   804          if (UNLIKELY(n < 0)) {
   805              switch (errno) {
   806              case EAGAIN:
   807                  request->conn->flags |= CONN_FLIP_FLAGS;
   808                  coro_yield(request->conn->coro, CONN_CORO_MAY_RESUME);
   809                  /* fallthrough */
   810              case EINTR:
   811  yield_and_read_again:
   812                  request->conn->flags |= CONN_MUST_READ;
   813                  coro_yield(request->conn->coro, CONN_CORO_MAY_RESUME);
   814                  continue;
   815              }
   816
   817              /* Unexpected error before reading anything */
   818              if (UNLIKELY(!total_read))
   819                  return HTTP_BAD_REQUEST;
   820
   821              /* Unexpected error, kill coro */
   822              coro_yield(request->conn->coro, CONN_CORO_ABORT);
   823              __builtin_unreachable();
   824          }
   825
   826          total_read += (size_t)n;
   827          buffer->len = (size_t)total_read;
   828
   829  try_to_finalize:
   830          switch (finalizer(total_read, buffer_size, helper, n_packets)) {
   831          case FINALIZER_DONE:
   832              request->conn->flags &= ~CONN_MUST_READ;
   833              buffer->value[buffer->len] = '\0';
   834
   835  #if defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
   836              save_to_corpus_for_fuzzing(buffer);
   837  #endif
   838
   839              return HTTP_OK;
   840
   841          case FINALIZER_TRY_AGAIN:
   842              continue;
   843
   844          case FINALIZER_YIELD_TRY_AGAIN:
   845              goto yield_and_read_again;
   846
   847          case FINALIZER_ERROR_TOO_LARGE:
   848              return HTTP_TOO_LARGE;
   849
   850          case FINALIZER_ERROR_TIMEOUT:
   851              return HTTP_TIMEOUT;
   852          }
   853      }
   854
   855      /* Shouldn't reach here. */
   856      coro_yield(request->conn->coro, CONN_CORO_ABORT);
   857      __builtin_unreachable();
   858      return HTTP_INTERNAL_ERROR;
   859  }
